# Concurrency & Reentrancy
# ---------------------------------------------------------------------------

class TestConcurrency:
    """Validate behavior under concurrent invocation."""

    @pytest.mark.asyncio
    async def test_concurrent_run_safe(self, concrete_skill):
        """Multiple concurrent run_safe calls should not corrupt state."""
        import asyncio

        results = await asyncio.gather(
            concrete_skill.run_safe({"cmd": "a"}),
            concrete_skill.run_safe({"cmd": "b"}),
            concrete_skill.run_safe({"cmd": "c"}),
            return_exceptions=True,
        )

        # All should succeed (or at least not raise unexpected exceptions)
        for r in results:
            if isinstance(r, Exception):
                pytest.fail(f"Unexpected exception: {r}")

    @pytest.mark.asyncio
    async def test_reentrant_call_after_failure(self, skill_instance):
        """After a failure, the skill should be reusable."""
        skill = FailingExecuteSkill(skill_instance)

        with pytest.raises(ValueError):
            await skill.run_safe({"cmd": "status"})

        # Reset failure flag for second attempt
        skill.execute_result = {"status": "recovered"}
        # Monkeypatch to succeed this time
        async def _succeed(self, payload):
            self.execute_called = True
            return {"status": "recovered"}
        skill.execute = _succeed.__get__(skill)

        result = await skill.run_safe({"cmd": "status"})
        assert result["status"] == "recovered"


